    template<typename T> requires gocpp::GoStruct<T>
    cancelCtx::operator T()
    {
        T result;
        result.Context = this->Context;
        result.mu = this->mu;
        result.done = this->done;
        result.children = this->children;
        result.err = this->err;
        result.cause = this->cause;
        return result;
    }

    template<typename T> requires gocpp::GoStruct<T>
    bool cancelCtx::operator==(const T& ref) const
    {
        if (Context != ref.Context) return false;
        if (mu != ref.mu) return false;
        if (done != ref.done) return false;
        if (children != ref.children) return false;
        if (err != ref.err) return false;
        if (cause != ref.cause) return false;
        return true;
    }

