    // propagateCancel arranges for child to be canceled when parent is.
    // It sets the parent context of cancelCtx.
    void rec::propagateCancel(cancelCtx* c, Context parent, canceler child)
    {
        c->Context = parent;

        auto done = rec::Done(gocpp::recv(parent));
        if(done == nullptr)
        {
            // parent is never canceled
            return;
        }

        //Go select emulation
        {
            int conditionId = -1;
            if(auto [gocpp_ignored , ok] = done.tryRecv(); ok) { conditionId = 0; }
            switch(conditionId)
            {
                case 0:
                    // parent is already canceled
                    rec::cancel(gocpp::recv(child), false, rec::Err(gocpp::recv(parent)), Cause(parent));
                    return;
                    break;
                default:
                    break;
            }
        }
        std::this_thread::yield();

        if(auto [p, ok] = parentCancelCtx(parent); ok)
        {
            // parent is a *cancelCtx, or derives from one.
            rec::Lock(gocpp::recv(p->mu));
            if(p->err != nullptr)
            {
                // parent has already been canceled
                rec::cancel(gocpp::recv(child), false, p->err, p->cause);
            }
            else
            {
                if(p->children == nullptr)
                {
                    p->children = gocpp::make(gocpp::Tag<gocpp::map<canceler, gocpp_id_11>>());
                }
                p->children[child] = gocpp_id_12 {};
            }
            rec::Unlock(gocpp::recv(p->mu));
            return;
        }

        if(auto [a, ok] = gocpp::getValue<afterFuncer>(parent); ok)
        {
            // parent implements an AfterFunc method.
            rec::Lock(gocpp::recv(c->mu));
            auto stop = rec::AfterFunc(gocpp::recv(a), [=]() mutable -> void
            {
                rec::cancel(gocpp::recv(child), false, rec::Err(gocpp::recv(parent)), Cause(parent));
            });
            c->Context = gocpp::Init<stopCtx>([=](auto& x) {
                x.Context = parent;
                x.stop = stop;
            });
            rec::Unlock(gocpp::recv(c->mu));
            return;
        }

        rec::Add(gocpp::recv(goroutines), 1);
        gocpp::go([&]{ [=]() mutable -> void
        {
            //Go select emulation
            {
                int conditionId = -1;
                if(auto [gocpp_ignored , ok] = rec::Done(gocpp::recv(parent)).tryRecv(); ok) { conditionId = 0; }
                else if(auto [gocpp_ignored , ok] = rec::Done(gocpp::recv(child)).tryRecv(); ok) { conditionId = 1; }
                switch(conditionId)
                {
                    case 0:
                        rec::cancel(gocpp::recv(child), false, rec::Err(gocpp::recv(parent)), Cause(parent));
                        break;
                    case 1:
                        break;
                }
            }
            std::this_thread::yield();
        }(); });
    }

    
