    // cancel closes c.done, cancels each of c's children, and, if
    // removeFromParent is true, removes c from its parent's children.
    // cancel sets c.cause to cause if this is the first time c is canceled.
    void rec::cancel(cancelCtx* c, bool removeFromParent, gocpp::error err, gocpp::error cause)
    {
        if(err == nullptr)
        {
            gocpp::panic("context: internal error: missing cancel error"_s);
        }
        if(cause == nullptr)
        {
            cause = err;
        }
        rec::Lock(gocpp::recv(c->mu));
        if(c->err != nullptr)
        {
            rec::Unlock(gocpp::recv(c->mu));
            // already canceled
            return;
        }
        c->err = err;
        c->cause = cause;
        auto [d, gocpp_id_13] = gocpp::getValue<gocpp::channel<gocpp_id_14>>(rec::Load(gocpp::recv(c->done)));
        if(d == nullptr)
        {
            rec::Store(gocpp::recv(c->done), closedchan);
        }
        else
        {
            close(d);
        }
        for(auto [child, gocpp_ignored] : c->children)
        {
            // NOTE: acquiring the child's lock while holding parent's lock.
            rec::cancel(gocpp::recv(child), false, err, cause);
        }
        c->children = nullptr;
        rec::Unlock(gocpp::recv(c->mu));

        if(removeFromParent)
        {
            removeChild(c->Context, c);
        }
    }

