    // WithDeadline returns a copy of the parent context with the deadline adjusted
    // to be no later than d. If the parent's deadline is already earlier than d,
    // WithDeadline(parent, d) is semantically equivalent to parent. The returned
    // [Context.Done] channel is closed when the deadline expires, when the returned
    // cancel function is called, or when the parent context's Done channel is
    // closed, whichever happens first.
    //
    // Canceling this context releases resources associated with it, so code should
    // call cancel as soon as the operations running in this [Context] complete.
    std::tuple<Context, CancelFunc> WithDeadline(Context parent, mocklib::Date d)
    {
        return WithDeadlineCause(parent, d, nullptr);
    }

    // WithDeadlineCause behaves like [WithDeadline] but also sets the cause of the
    // returned Context when the deadline is exceeded. The returned [CancelFunc] does
    // not set the cause.
    std::tuple<Context, CancelFunc> WithDeadlineCause(Context parent, mocklib::Date d, gocpp::error cause)
    {
        gocpp::Defer defer;
        try
        {
            if(parent == nullptr)
            {
                gocpp::panic("cannot create context from nil parent"_s);
            }
            if(auto [cur, ok] = rec::Deadline(gocpp::recv(parent)); ok && rec::Before(gocpp::recv(cur), d))
            {
                // The current deadline is already sooner than the new one.
                return WithCancel(parent);
            }
            auto c = gocpp::InitPtr<timerCtx>([=](auto& x) {
                x.deadline = d;
            });
            rec::propagateCancel(gocpp::recv(c->cancelCtx), parent, c);
            auto dur = time::Until(d);
            if(dur <= 0)
            {
                // deadline has already passed
                rec::cancel(gocpp::recv(c), true, DeadlineExceeded, cause);
                return {c, [=]() mutable -> void
                {
                    rec::cancel(gocpp::recv(c), false, Canceled, nullptr);
                }};
            }
            rec::Lock(gocpp::recv(c->cancelCtx.mu));
            defer.push_back([=]{ rec::Unlock(gocpp::recv(c->cancelCtx.mu)); });
            if(c->cancelCtx.err == nullptr)
            {
                c->timer = time::AfterFunc(dur, [=]() mutable -> void
                {
                    rec::cancel(gocpp::recv(c), true, DeadlineExceeded, cause);
                });
            }
            return {c, [=]() mutable -> void
            {
                rec::cancel(gocpp::recv(c), true, Canceled, nullptr);
            }};
        }
        catch(gocpp::GoPanic& gp)
        {
            defer.handlePanic(gp);
        }
    }

    // A timerCtx carries a timer and a deadline. It embeds a cancelCtx to
    // implement Done and Err. It implements cancel by stopping its timer then
    // delegating to cancelCtx.cancel.
    
    template<typename T> requires gocpp::GoStruct<T>
    timerCtx::operator T()
    {
        T result;
        result.cancelCtx = this->cancelCtx;
        result.timer = this->timer;
        result.deadline = this->deadline;
        return result;
    }

